WHERE NOT EXISTS (SELECT 1 FROM "Product" p WHERE p.brand = 'UPL / Isagro' AND p.name = 'Cuprocaffaro Micro');
INSERT INTO "SubstanceDose" (id, dose, "substanceId", "productId", "createdAt", "updatedAt")
SELECT gen_random_uuid(), 37.5, s.id, p.id, NOW(), NOW()
